settings.cssBlock:
#chat .mes .avatar {
    border: unset !important;
}

/* Theme Colorization */
.drawer-icon,
#rightSendForm>div,
#leftSendForm>div,
.options-content a,
.list-group-item,
.mes_button {
    transition: all 0.5s ease !important;
}
.drawer-icon.openIcon,
#rightSendForm>div:hover,
#leftSendForm>div:hover,
.options-content a:hover,
.list-group-item:hover,
.mes_button:hover {
    color: var(--customThemeColor) !important;
}
#left-nav-panel,
#right-nav-panel,
.drawer-content,
#character_popup,
#logprobsViewer,
#floatingPrompt,
#cfgConfig {
    border-top: 1px solid color-mix(in srgb, var(--customThemeColor) 50%, transparent) !important;
}
#left-nav-panel,
#right-nav-panel,
.drawer-content,
#WorldInfo {
    @media screen and (max-width: 1000px) {
        border-bottom: 1px solid color-mix(in srgb, var(--customThemeColor) 50%, transparent);
    }
}

.drawer-content,
.fillLeft,
.fillRight {
    transition-property: unset;
    transition-duration: unset;
    transition-timing-function: unset;
    transition-behavior: unset;
}

/* Force Fixed Menu Height */
.fillLeft,
.fillRight,
#left-nav-panel,
#right-nav-panel {
    min-height: calc(100dvh - var(--topBarBlockSize)) !important;
    height: calc(100dvh - var(--topBarBlockSize)) !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
}

/* Dynamic Menu Height */
.drawer-content {
    max-height: calc(100dvh - var(--topBarBlockSize) - var(--formSheldHeight) - 5px) !important;
}
@media screen and (max-width: 1000px) {
    .drawer-content,
    .fillLeft, .fillRight,
    #left-nav-panel, #right-nav-panel {
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--formSheldHeight) + 4px) !important;
    }

    #floatingPrompt,
    #cfgConfig,
    #logprobsViewer,
    #movingDivs > div,
    #character_popup {
        max-height: calc(100dvh - var(--topBarBlockSize)) !important;
        padding-bottom: 15px !important;
    }
}

/* Disable Border Radius */
:root {
    --avatar-base-border-radius: 0 !important;
}
*, *::before, *::after {
    border-radius: 0 !important;
    border-top-left-radius: 0 !important;
    border-top-right-radius: 0 !important;
    border-bottom-left-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
    outline-radius: 0 !important;
    -moz-outline-radius: 0 !important;
}
body.whisperstyle #chat .mes::before {
    border-radius: 0 !important;
}
body.ripplestyle #chat .mes .mesAvatarWrapper .avatar,
body.ripplestyle #chat .mes .mesAvatarWrapper .avatar img,
#extensionTopBar,
body:has(#extensionConnectionProfiles.visible) #extensionTopBar,
#rm_ch_create_block .avatar img {
    border-radius: 0 !important;
}
@media screen and (max-width: 1000px) {
    #send_form {
        border-radius: 0 !important;
    }
}
svg * {
    rx: 0 !important;
    ry: 0 !important;
}

input[type=number]::-webkit-outer-spin-button,
input[type=number]::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
}
input[type=number] {
    -moz-appearance:textfield;
}

.world_entry .inline-drawer-header {
    padding: 2px 10px;
}
.wi-card-entry {
    padding: 2px;
    margin: 2px;
}

.mes_reasoning_header > .icon-svg {
    display: block;
    opacity: 1 !important;
}

.mes_text p {
    text-align: justify;
    text-justify: inter-ideograph;
    }

.mes .ch_name,
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    visibility: hidden !important;
    opacity: 0 !important;
    transition: all var(--messageDetailsAnimationDuration) cubic-bezier(0.4, 0, 0.2, 1),
                visibility 0s ease var(--messageDetailsAnimationDuration) !important;
    z-index: 10 !important;
    pointer-events: auto !important;
}

.mes:hover .ch_name,
.mes:hover .mesIDDisplay,
.mes:hover .mes_timer,
.mes:hover .tokenCounterDisplay,
.mes.active-message .ch_name,
.mes.active-message .mesIDDisplay,
.mes.active-message .mes_timer,
.mes.active-message .tokenCounterDisplay {
    visibility: visible !important;
    opacity: 1 !important;
    transition: all var(--messageDetailsAnimationDuration) cubic-bezier(0.4, 0, 0.2, 1),
                visibility var(--messageDetailsAnimationDuration) ease !important;
}

.mes .mes_reasoning_details {
    opacity: 0;
    max-height: 1px;
    transform: translateY(-10px);
    pointer-events: none;
    transition:
        opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1),
        transform 0.6s cubic-bezier(0.4, 0, 0.2, 1),
        max-height 0.3s cubic-bezier(0, 0, 0.2, 1);
    will-change: opacity, transform;
}
.mes:hover .mes_reasoning_details,
.mes.active-message .mes_reasoning_details {
    opacity: 1;
    visibility: visible !important;
    transform: translateY(0);
    max-height: 100%;
    pointer-events: auto;
}

body.flatchat,
body.bubblechat,
body.ripplestyle {
    .mes .ch_name,
    .mes .mesIDDisplay,
    .mes .mes_timer,
    .mes .tokenCounterDisplay {
        margin-top: -40px;
        background: none;
    }

    .mes:hover .ch_name,
    .mes:hover .mesIDDisplay,
    .mes:hover .mes_timer,
    .mes:hover .tokenCounterDisplay,
    .mes.active-message .ch_name,
    .mes.active-message .mesIDDisplay,
    .mes.active-message .mes_timer,
    .mes.active-message .tokenCounterDisplay {
        margin-top: unset;
        background: unset;
    }
}

body.flatchat,
body.bubblechat,
body.documentstyle,
body.ripplestyle {
    .mes .ch_name,
    .mes .mesIDDisplay,
    .mes .mes_timer,
    .mes .tokenCounterDisplay {
        transform: translateY(-40px);
    }

    .mes:hover .ch_name,
    .mes:hover .mesIDDisplay,
    .mes:hover .mes_timer,
    .mes:hover .tokenCounterDisplay,
    .mes.active-message .ch_name,
    .mes.active-message .mesIDDisplay,
    .mes.active-message .mes_timer,
    .mes.active-message .tokenCounterDisplay {
        transform: translateY(0);
    }
}

.character_select.is_fav .ch_name::before,
.group_select.is_fav .ch_name::before,
.group_member.is_fav .ch_name::before {
    animation: fadePulse 1s ease-in-out infinite;
}
@keyframes fadePulse {
    0%, 100% { opacity: 0.6; }
    50% { opacity: 1; }
}

body.echostyle #chat {
    .mes[is_user="true"] {
        .name_text {
                display: inline-block !important;
                margin-right: 5px;
            }
        .mes_text,
            .last_mes .mes_text {
                padding: 10px 20px !important;
                min-height: unset !important;
            }
        .mes_text::before {
            display: none !important;
        }
    }
}

body.echostyle #chat {
    @media screen and (max-width: 1000px) {
        .mes[is_user="true"],
        .mes[is_user="false"] {
            .mes_text,
            .last_mes .mes_text {
                padding: 10px 20px !important;
                min-height: unset !important;
            }
        }
        .mes_text::before {
            display: none !important;
        }
    }

    .ch_name {
        .name_text {
            display: inline-block !important;
            margin-right: 5px;
        }
    }
}

body.ripplestyle #chat .mes[is_user="true"] {
    .mesAvatarWrapper {
        margin-top: 35px;
        top: 35px;
    }
    .avatar {
        display: none !important;
    }
    .mes_timer,
    .mesIDDisplay,
    .tokenCounterDisplay {
        margin-left: 10px;
    }
}

/* Mobile Hidden Scrollbar */
@media screen and (max-width: 1000px) {
    * {
        scrollbar-width: none !important;
        -ms-overflow-style: none !important;
    }
    *::-webkit-scrollbar {
        display: none !important;
    }

    .scrollableInner,
    #form_create,
    #rm_print_characters_block,
    #extensionSideBar #extensionSideBarContainer {
        padding: 0 !important;
    }
}

/* Mobile Input Field */
@media screen and (max-width: 1000px) {
    #form_sheld {}

    body:has([data-slide-toggle="shown"]) #send_form  {
        border-radius: 0 !important;
    }

    /* Mobile Chat Input Overall */
    #send_form {
        margin-bottom: 0 !important;
        min-height: 100% !important;
        padding: 5px 15px;
        padding-top: 8px;
        border-radius: 15px 15px 0 0 !important;
        transition: all 0.5s ease;

        &:focus-within {
            border-top: 1.25px solid var(--customThemeColor) !important;
            box-shadow: 0 0 5px var(--customThemeColor);
        }

        &.compact {
            #leftSendForm,
            #rightSendForm {
                display: flex;
                align-items: center;
                justify-content: center;
                flex-wrap: nowrap;
                width: unset;
            }
        }
    }

    /* Mobile Chat Menu */
    #nonQRFormItems {
        display: grid;
        grid-template-columns: 1fr 1fr;
        grid-template-rows: auto auto;
        grid-template-areas:
        "textarea textarea"
        "left right";
        gap: 0;
        padding: 0;

        #send_textarea {
            grid-area: textarea;
            box-sizing: border-box;
            width: 100%;
            padding: 5px 6px;
            margin-top: 3px;
        }
    }

    /* Mobile Left & Right Chat Menu */
    #leftSendForm,
    #rightSendForm {
        margin: 3px 0;
    }
    #leftSendForm {
        grid-area: left;
        display: flex;
        align-items: center;
        justify-content: flex-start !important;
    }
    #rightSendForm {
        grid-area: right;
        display: flex;
        align-items: center;
        justify-content: flex-end !important;
    }

    #rightSendForm > div,
    #leftSendForm > div,
    #nonQRFormItems #options_button {
        font-size: 16px;
    }
    #nonQRFormItems #options_button {
        margin-right: 10px;
    }

    #leftSendForm>div {
        width: var(--bottomFormBlockSize) !important;
    }
}

@media (max-width: 1000px) {
    body:not(.echostyle) .name_text {
        width: unset !important;
    }
    body.whisperstyle:not(.big-avatars) #chat {
        .mes {
            padding-top: 75px !important;
        }
    }
}

@media screen and (max-width: 1000px) {
    #send_form {
        padding-bottom: 23px;
    }
}

#form_sheld {
    margin-bottom: 5px;

    @media only screen and (min-width: 1024px) and (-webkit-min-device-pixel-ratio: 2) and (pointer: fine) {
        margin-bottom: 22.5px;
    }
}

.drawer-content {
    top: -3px !important;
}
.fillLeft,
.fillRight {
    width: 100dvw !important;
    min-width: 100dvw !important;
}

/* Mobile QR position adjustment */
@media screen and (max-width: 1000px) {
    #send_form.compact {
        flex-direction: column;
    }

    #file_form {
        order: 1 !important;
    }
    #nonQRFormItems {
        order: 2 !important;
    }
    #qr--bar {
        order: 3 !important;
    }

    #leftSendForm {
        padding-left: 6px;
    }
    #rightSendForm {
        padding-right: 6px;
    }
}

@media screen and (max-width: 1000px) {
    body.big-avatars #HotSwapWrapper .hotswap.avatars_inline {
        max-height: unset;
    }
    #HotSwapWrapper:hover .hotswap.avatars_inline {
        max-height: unset;
        overflow: unset;
        transition: unset;
    }
    #HotSwapWrapper:not(:hover) .hotswap.avatars_inline {
        transition: unset;
    }
    .hotswap.avatars_inline {
        flex-wrap: nowrap !important;
        overflow-x: auto !important;
        overflow-y: hidden !important;
        padding-right: 30px !important;

        *:focus {
            outline: none;
        }
    }
}
